import { expect, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test(
    "Fields that cannot be parsed get low confidence",
    { tag: "@DOC-03" },
    async ({ apiAs }) => {
      // Arrange: signed-in member and a vendor in draft status
      const member = await apiAs("member");
      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("DOC03 Vendor"),
          category: "services",
          contact_email: `doc03.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.test`,
        },
      });
      expect(vendorResponse.status()).toBe(201);
      const vendor = await vendorResponse.json();
      expect(vendor.status).toBe("draft");

      // Arrange: insurance certificate whose expiry date is "next spring"
      const certificate = Buffer.from(
        "INSURANCE CERTIFICATE\nPolicy holder: DOC-03 test\nExpiry date: next spring\n",
        "utf-8",
      );

      // Act: upload the document
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance-certificate.txt",
            mimeType: "text/plain",
            buffer: certificate,
          },
        },
      });

      // Assert: upload accepted
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();
      expect(document.kind).toBe("insurance_certificate");

      // Act: wait for background processing to finish
      await expect
        .poll(
          async () => {
            const response = await member.get(`/api/documents/${document.id}`);
            expect(response.status()).toBe(200);
            return (await response.json()).status as string;
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .not.toBe("processing");

      const processed = await (await member.get(`/api/documents/${document.id}`)).json();
      expect(processed.status).toBe("extracted");

      // Act: fetch the extraction
      const extractionResponse = await member.get(`/api/documents/${document.id}/extraction`);

      // Assert: expiry_date is null with confidence below 0.5
      expect(extractionResponse.status()).toBe(200);
      const extraction = await extractionResponse.json();
      expect(extraction.fields).toHaveProperty("expiry_date");
      const expiry = extraction.fields.expiry_date as { value: string | null; confidence: number };
      expect(expiry.value).toBeNull();
      expect(expiry.confidence).toBeLessThan(0.5);
    },
  );
});
